) VALUES (
  '22222222-2222-4222-b222-000000000001', '11111111-1111-4111-a111-111111111101', 'Nordic Ceramic Dinner Plate', 'nordic-ceramic-dinner-plate', 'Elevate your everyday dining with our Nordic Ceramic Dinner Plate. Fired at over 1,280°C for exceptional durability and chip resistance, each plate features a tactile unglazed rim contrasting with a silky matte glazed center. Microwave, oven, and dishwasher safe.', 'Minimal stoneware for everyday dining.',
  1499, 1899, 'KC-SKU-001', 'Glazed Stoneware', 'Ivory Cream', '10.5 inch (27 cm)',
  4.9, 142, 45,
  true, true, false, true
